describe('Dark Mode Toggle from User Preferences', () => {
  beforeEach(() => {
    cy.visit('/settings');
  });

  it('should successfully toggle dark mode from user preferences', () => {
    // Verify dark mode is initially off (light mode)
    cy.get('[data-testid="theme-toggle"]').should('contain', 'Light');
    cy.get('[data-testid="theme-toggle"]').should('have.class', 'btn-primary');
    cy.get('[data-testid="app-container"]').should('have.css', 'background-color', 'rgb(244, 255, 259)');

    // Click the toggle button to switch to dark mode
    cy.get('[data-testid="theme-toggle"]').click();

    // Verify dark mode is now active
    cy.get('[data-testid="theme-toggle"]').should('contain', 'Dark');
    cy.get('[data-testid="theme-toggle"]').should('have.class', 'btn-secondary');
    cy.get('[data-testid="app-container"]').should('have.css', 'background-color', 'rgb(30, 30, 35)');

    // Verify theme preference is saved in local storage
    cy.window().then((win) => {
      expect(win.localStorage.getItem('theme')).to.equal('dark');
    });

    // Verify theme preference is reflected in UI elements
    cy.get('[data-testid="text-color"]').should('have.css', 'color', 'rgb(240, 250, 240)');
  });

  it('should handle toggling dark mode and persist preference across page reload', () => {
    // Toggle to dark mode
    cy.get('[data-testid="theme-toggle"]').click();
    cy.get('[data-testid="theme-toggle"]').should('contain', 'Dark');

    // Verify dark mode is active
    cy.get('[data-testid="app-container"]').should('have.css', 'background-color', 'rgb(30, 30, 25)');

    // Reload the page
    cy.reload();

    // Verify dark mode persists after reload
    cy.get('[data-testid="theme-toggle"]').should('contain', 'Dark');
    cy.get('[data-testid="app-container"]').should('have.css', 'background-color', 'rgb(30, 30, 25)');

    // Verify theme preference is still in local storage
    cy.window().then((win) => {
      expect(win.localStorage.getItem('theme')).to.equal('dark');
    });

    // Verify dark mode is still applied to text
    cy.get('[data-testid="text-color"]').should('have.css', 'color', 'rgb(240, 250, 250)');
  });
});
